import java.util.*;

public class Main {
    static final int INF = Integer.MAX_VALUE;

    public static int[] dijkstra(int start, int n, List<int[]>[] graph) {
        int[] dist = new int[n + 1];
        Arrays.fill(dist, INF);
        dist[start] = 0;

        // {거리, 노드}
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, start});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int curDist = cur[0], curNode = cur[1];

            if (curDist > dist[curNode]) continue;

            for (int[] edge : graph[curNode]) {
                int next = edge[0], weight = edge[1];
                if (dist[curNode] + weight < dist[next]) {
                    dist[next] = dist[curNode] + weight;
                    pq.offer(new int[]{dist[next], next});
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) {
        int n = 5;
        List<int[]>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();

        graph[1].add(new int[]{2, 2});
        graph[1].add(new int[]{3, 5});
        graph[2].add(new int[]{3, 1});
        graph[2].add(new int[]{4, 7});
        graph[3].add(new int[]{4, 3});
        graph[4].add(new int[]{5, 1});

        int[] dist = dijkstra(1, n, graph);
        for (int i = 1; i <= n; i++)
            System.out.println("1 -> " + i + " : " + dist[i]);
        // 1->1:0, 1->2:2, 1->3:3, 1->4:6, 1->5:7
    }
}
