#include <iostream>

#include <vector>

#include <queue>

#include <climits>

using namespace std;

const int INF = INT_MAX;

vector<int> dijkstra(int start, int n, vector<vector<pair<int,int>>>& graph) {

    vector<int> dist(n + 1, INF);

    dist[start] = 0;

    // {거리, 노드}

    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;

    pq.push({0, start});

    while (!pq.empty()) {

        auto [curDist, curNode] = pq.top();

        pq.pop();

        if (curDist > dist[curNode]) continue;

        for (auto [next, weight] : graph[curNode]) {

            if (dist[curNode] + weight < dist[next]) {

                dist[next] = dist[curNode] + weight;

                pq.push({dist[next], next});

            }

        }

    }

    return dist;

}

int main() {

    int n = 5;

    vector<vector<pair<int,int>>> graph(n + 1);

    graph[1].push_back({2, 2});

    graph[1].push_back({3, 5});

    graph[2].push_back({3, 1});

    graph[2].push_back({4, 7});

    graph[3].push_back({4, 3});

    graph[4].push_back({5, 1});

    vector<int> dist = dijkstra(1, n, graph);

    for (int i = 1; i <= n; i++)

        cout << "1 -> " << i << " : " << dist[i] << "\n";

    // 1->1:0, 1->2:2, 1->3:3, 1->4:6, 1->5:7

    return 0;

}

